import{_ as s,l as o,o as e,c as l,v as r,p as h,x as t,d,i as n,S as c}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"Christofides","description":"","frontmatter":{"title":"Christofides","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/christofides.md","filePath":"cs/christofides.md","lastUpdated":1789023840000}'),p={name:"cs/christofides.md"};function m(T,a,f,S,P,_){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="christofides" tabindex="-1">Christofides <a class="header-anchor" href="#christofides" aria-label="Permalink to &quot;Christofides&quot;">​</a></h1><div class="epigraph"><p>度量 TSP：MST 加倍是 2-近似；对奇度点最小匹配再欧拉捷径，最坏 $3/2$。</p><footer>—— 据 Christofides, Worst-Case Analysis of a New Heuristic for the Travelling Salesman Problem, 1976；CLRS 第 35.2 节整理</footer></div><p>上一课<a href="/cs/set-cover-greedy">集合覆盖</a>是对数比。度量 TSP：三角不等式。主干<a href="/cs/hamiltonian-tsp-exact">哈密顿精确</a>是指数。缺口是 Christofides \\(3/2\\)。不重写 Held–Karp。后课 LP 舍入。一般非度量 TSP 无常数比（除非 P=NP）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>MST 权 \\(\\le\\mathrm{OPT}\\)。欧拉于加倍 MST，捷径（三角）\\(\\le 2\\,\\mathrm{MST}\\le 2\\,\\mathrm{OPT}\\)。Christofides：MST 上奇度点集 \\(O\\)，最小权完美匹配 \\(M\\)，\\(w(M)\\le\\mathrm{OPT}/2\\)（最优环在 \\(O\\) 上两条匹配）。MST\\(\\cup M\\) 欧拉，捷径 \\(\\le\\mathrm{MST}+w(M)\\le 3/2\\,\\mathrm{OPT}\\)。</p><p>缺口是匹配这一步，不是 2-近似 MST 走两遍。</p><h3 id="必须度量" tabindex="-1">必须度量 <a class="header-anchor" href="#必须度量" aria-label="Permalink to &quot;必须度量&quot;">​</a></h3><p>无三角，捷径可能变差。城市距离要满足三角（或图最短路度量）。</p><p><span class="marginnote">Christofides 1976。近年 \\(3/2-\\varepsilon\\) 的改进点名。后课 LP 舍入是另一近似范式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>求 MST。找奇度点，完全图上距离为原度量，最小匹配（<a href="/cs/hungarian-km">KM</a> 或一般带权）。Hierholzer 欧拉，捷径去重复顶点。</p>',11)),(e(),h(c,null,{default:t(()=>[n(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MST%5B%22MST%22%5D%20--%3E%20ODD%5B%22%E5%A5%87%E5%BA%A6%E7%82%B9%E5%8C%B9%E9%85%8D%22%5D%0A%20%20ODD%20--%3E%20EU%5B%22%E6%AC%A7%E6%8B%89%E5%9B%9E%E8%B7%AF%22%5D%0A%20%20EU%20--%3E%20SH%5B%22%E4%B8%89%E8%A7%92%E6%8D%B7%E5%BE%84%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>实现注意匹配是度量完全图。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>奇度点偶数个（握手）。最优 TSP 在奇度点上拆成两条匹配，较小者 \\(\\le\\mathrm{OPT}/2\\)。与欧拉课：这里边可重复再捷径。与精确 TSP：近似多项式。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写路径 TSP 变体全文。不写欧氏 PTAS（Arora）。后课默认：度量 TSP \\(3/2\\) Christofides。下一课 LP 松弛与舍入。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>度量 TSP：MST+奇度匹配+\\(3/2\\)。</li><li>无三角则无此保证。</li><li>精确仍 NPC。</li><li>出处：Christofides, 1976；CLRS 第 35.2 节。</li></ul>',7))])}const C=s(p,[["render",m]]);export{E as __pageData,C as default};
